// Read-only offline observations generated by the C++ executable.
(() => {
  const $=id=>document.getElementById(id);
  const data=window.P03_CORE_SNAPSHOT;
  if(!data||data.schema!=='p03.offline.v1'){
    $('finding').textContent='C++ 快照未加载。请重新执行导出流程；不使用手写样本回退。';
    document.querySelectorAll('[data-step]').forEach(b=>b.disabled=true);
    return;
  }
  const descriptions=[
    '本地接受买开请求并预占资源。没有执行外发。',
    '成交明细 t1 已记账，剩余数量继续保留订单风险。',
    '撤单终态给出累计成交 2 手，账本只有 1 手；差额进入暂记，不能直接释放。',
    '迟到 t2 补齐成交；重复 t2 返回 Duplicate，没有再次记账或消费资源。'
  ];
  const indices=[1,2,4,6];
  const labels=[['B / BOOKED','成交已记账'],['H / SUSPENSE','累计证据待补明细'],['P / POSSIBLE','仍可能成交'],['L / RELEASED','确认未成交可释放'],['V / UNRESOLVED','未决数量']];
  const cells=values=>{const row=document.createElement('tr');for(const value of values){const cell=document.createElement('td');cell.textContent=value;row.append(cell);}return row;};
  function show(index){
    const frame=data.frames[indices[index]],order=frame.order,p=order.parts;
    for(const [id,value] of Object.entries({external:`${order.execution} / ${order.consistency}`,booked:`${p[0]} / ${order.quantity}`,cancel:order.cancel,delta:frame.positions[0],position:frame.positions[0],riskBooked:p[0],riskPending:p[1]+p[2]+p[4],riskReleased:p[3],eventType:frame.event,sequence:frame.sequence,tradeId:frame.trade_id||'—',payload:JSON.stringify({error:frame.error,applied:frame.applied,invariant:frame.invariant,ledger_records:frame.trade_records,funds_required:frame.funds_required},null,2),finding:descriptions[index],dedup:`${frame.trade_records} 笔独立记账${frame.error==='Duplicate'?' / Duplicate 已拒绝重复':''}`,footerScene:`C++ SNAPSHOT · SEQ ${frame.sequence} · ${data.provenance.run}`,eventCount:`${frame.sequence} EVENTS`,reviewState:order.consistency,sum:`${order.quantity} = ${p.join(' + ')}`}))$(id).textContent=value;
    $('parts').replaceChildren(...labels.map(([name,meaning],i)=>cells([name,p[i],meaning])));
    $('events').replaceChildren(...data.frames.slice(0,frame.sequence).map(f=>cells([String(f.sequence).padStart(2,'0'),'LocalFixture',f.event,f.order?.id||'—',`${f.error} / applied=${f.applied}${f.trade_id?' / '+f.trade_id:''}`])));
    document.querySelectorAll('[data-step]').forEach(button=>{const active=Number(button.dataset.step)===index;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active));});
  }
  document.querySelectorAll('[data-step]').forEach(button=>button.onclick=()=>show(Number(button.dataset.step)));
  $('snapshotProvenance').textContent=`${data.provenance.build} · 导出 ${data.provenance.generated_utc} · SHA256 ${data.provenance.snapshot_sha256.slice(0,16)}…`;
  show(0);
})();
